<?php
function rd_registration_panels($b,$rows){
 if($b['kind']!=='Register')return;$editable=$b['status']==='Review'&&om_allowed()&&(access_profile()==='Admin'||(int)$b['created_by']===current_user()['id']);
 echo '<div class="rd-history-actions"><a class="btn ghost sm" href="order_monitor_action.php?download=registration_process&amp;platform='.e($b['platform']).'&amp;format=xlsx">Download Correction / Late Dispatch History</a><a class="btn ghost sm" target="_blank" href="order_monitor_action.php?download=registration_process&amp;platform='.e($b['platform']).'&amp;format=print">Print Process History</a></div>';
 if(!empty($b['meta']['late_registration']))echo '<div class="alert warn"><b>Late-recorded dispatch review.</b> Confirmation creates the selected new orders and deducts physical stock once on each actual dispatch date. No reservation remains. Parent upload #'.(int)$b['meta']['parent_upload_id'].'. Reason: '.e($b['meta']['reason']).'. Actual dates, encoding time and stock movements are retained.</div>';
 if($editable&&isset($_SESSION['rd_bulk'][$b['id']])){$saved=$_SESSION['rd_bulk'][$b['id']];$plan=$saved['plan'];if((int)$plan['revision']!==(int)$b['revision'])echo '<div class="alert warn">Bulk preview is out of date. Reopen the item correction and select Review Bulk Correction again.</div>';else{
 echo '<section class="rd-review"><h3>Review Bulk Product Correction</h3><p>'.e($plan['sku'].' / '.$plan['variation']).'</p><p><b>Corrected product:</b> '.e(rd_component_label($plan['components'])).'</p><p>Same platform, shop, SKU identity and variation only. Registered, removed and other uploads are protected.</p>';om_form('om_bulk_mapping_apply',['upload_id'=>$b['id'],'bulk_token'=>$saved['token']]);echo '<label class="om-inline"><input type="checkbox" class="rd-select-all" checked> Select all eligible matching rows · all review pages</label><div class="rd-table"><table class="table"><thead><tr><th>Select</th><th>Order ID / source row</th><th>Uploaded Qty</th><th>Previous mapping</th><th>After correction</th></tr></thead><tbody>';foreach($plan['matches'] as $m)echo '<tr><td><input type="checkbox" name="selected_rows[]" value="'.(int)$m['row'].'" checked aria-label="Select '.e($m['order']).' row '.(int)$m['row'].'"></td><td>'.e($m['order']).'<br>Row '.(int)$m['row'].'</td><td>'.(int)$m['qty'].'</td><td>'.e(rd_component_label($m['before'])?:$m['previous_issue']).'</td><td>'.e(rd_component_label($plan['components'])).'</td></tr>';echo '</tbody></table></div><p><b>Stock effect: 0.</b> Selected rows will be revalidated. '.($plan['save_mapping']?'Verified mapping will be saved for future uploads.':'Future mapping will be retained on registration confirmation.').'</p><label class="om-inline"><input type="checkbox" name="bulk_ack" value="1" required> I confirm the selected orders, product and pieces per uploaded unit.</label><button class="btn primary">Yes, Apply Bulk Mapping &amp; Revalidate</button></form></section>';
 }}
 if($editable&&empty($b['meta']['late_registration'])){$candidates=[];foreach($rows as $r)if(empty($r['order_record'])&&!oi_exclusion($b,$r['order'])&&in_array($r['status'],['Shipped','Delivered','Completed'],true))$candidates[]=$r;if($candidates){echo '<details class="rd-review"><summary>Review Late-recorded Dispatch · '.count($candidates).' new dispatched orders</summary><p>For orders already picked up before encoding. Existing orders use Update Status. This step creates a separate review; it does not deduct stock.</p>';om_form('om_late_stage',['upload_id'=>$b['id'],'revision'=>$b['revision']]);echo '<label class="om-inline"><input type="checkbox" class="rd-select-all"> Select all listed new dispatched orders</label><div class="rd-table"><table class="table"><thead><tr><th>Select</th><th>Order ID</th><th>Source status</th><th>Actual Dispatch Date</th></tr></thead><tbody>';foreach($candidates as $r){$d=om_date_details($r['lines']);$date=$d['shipping_dates']?substr(max($d['shipping_dates']),0,10):'';$key=hash('sha256',$r['order']);echo '<tr><td><input type="checkbox" name="orders[]" value="'.e($r['order']).'" aria-label="Select '.e($r['order']).'"></td><td>'.e($r['order']).'</td><td>'.e($r['status']).'</td><td><input type="date" name="dispatch_dates['.$key.']" value="'.e($date).'" max="'.date('Y-m-d').'" aria-label="Actual dispatch date '.e($r['order']).'">'.($date?'<span class="small muted">Platform shipping date</span>':'<span class="small muted">No shipping date in source · enter verified actual date</span>').'</td></tr>'; }echo '</tbody></table></div><label>Reason / supporting reference<input name="reason" minlength="3" required maxlength="2000"></label><label class="om-inline"><input type="checkbox" name="late_ack" value="1" required> I verified actual pickup and dates; these items were not already deducted, included in Beginning Balance, or covered by another outflow.</label><p class="small muted">Closed cutoffs, later inventory counts and negative historical balances remain blocked for Admin reconciliation.</p><button class="btn secondary">Review Selected Late Dispatches · No Stock Change</button></form></details>';}}
 $events=om_query("SELECT e.*,u.name actor FROM om_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.upload_id=? AND e.event_type IN ('Bulk mapping corrected','Late dispatch recorded','Late dispatch review created') ORDER BY e.id DESC LIMIT 10",[$b['id']])->fetchAll();if($events){echo '<details class="rd-review"><summary>Correction / Late Dispatch History · Latest 10 Events</summary>';foreach($events as $event){$d=json_decode($event['details_json'],true)?:[];echo '<article class="rd-event"><b>'.e($event['event_type']).'</b><p>'.e($event['created_at'].' · '.$event['actor']).'</p><p>Reason: '.e($d['reason']??'').'</p>';if(!empty($d['changes']))foreach($d['changes'] as $c)echo '<p>'.e($c['order']).' · Row '.(int)$c['row'].' · '.e(rd_component_label($c['before'])).' → '.e(rd_component_label($c['after'])).' · stock effect 0</p>';if(!empty($d['actual_event_date']))echo '<p>Actual dispatch: '.e($d['actual_event_date']).'</p>';foreach($d['effects']??[] as $effect)echo '<p>'.e($effect['sku']).' · Physical '.(int)$effect['physical_before'].' → '.(int)$effect['physical_after'].' · Reserved '.(int)$effect['reserved_before'].' → '.(int)$effect['reserved_after'].' · Outflow #'.(int)$effect['outflow_id'].'</p>';if(!empty($d['review_upload_id']))echo '<a class="btn ghost sm" href="?page=outflow&amp;upload_id='.(int)$d['review_upload_id'].'">Open Late Dispatch Review #'.(int)$d['review_upload_id'].'</a>';echo '</article>';}echo '</details>';}
 echo '<script src="assets/registration_extensions.js?v=5.9.33" defer></script><link rel="stylesheet" href="assets/registration_extensions.css?v=5.9.33">';
}
